// Building from attempt 2 (best at 40.8%) with three targeted fixes for the
// remaining failure modes:
//
// 1. `!`-loop / dead-end inside spans (malformed_constrained_content, unterminated):
//    When the parser's grammar enters a near-dead-end (≤2 valid tokens, e.g. only `!`
//    after a trailing space or `>` character that traps the span), we NOW call
//    DeadEndDetection before each constrained step. If a dead-end is detected, we
//    invoke CloseSpanWithinBudget(50) which is dead-end-aware and rolls back to the
//    last complete prefix (e.g., rolls back `n1 * p1 >` to `n1 * p1`) and emits `>>`.
//    Crucially, we do NOT break after this escape — the loop continues so subsequent
//    spans can still be generated.
//
// 2. `final_span_unclosed` via EOS (12 cases in attempt 8, 7 in attempt 2):
//    When SafeRepetitionPenaltyStep returns EOS inside an open span, we call
//    CloseSpanWithinBudget(min(remaining, 30)) before breaking to rescue the span.
//    Penalty stays at 4.0 (reducing it to 2.0 hurt accuracy in attempt 7).
//
// 3. `final_span_unclosed` via budget (budget guard):
//    Unchanged from attempt 2: when remaining ≤ closeReserve=80 inside a span,
//    delegate the whole remaining budget to CloseSpanWithinBudget. After forced
//    close, break (no more generation needed).
//
// Key differences from attempt 8 (which regressed):
//   - No maxSpanLength cap (caused span_absent=8 by breaking loop after first cap hit)
//   - closeReserve stays at 80 (not 150 which burned budget too early)
//   - Dead-end detection CONTINUES the loop instead of breaking
//   - No `**` in guidance (was causing final_span_invalid)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (budget-guard / remaining <= closeReserve branch):
//     CloseSpanWithinBudget postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`.
//     Both the closed path (insideOut=false, implication vacuous) and the still-open path
//     preserve the invariant. ✓
//
//   (!insideConstrainedOut branch):
//     When RenderedEndsWith detects "<<", we set currentConstrainedOut := [], which satisfies
//     IsValidPrefix([]) by the method precondition `parser.IsValidPrefix([])`. Otherwise
//     insideConstrainedOut stays false making the implication vacuous. ✓
//
//   (IsCompletePrefix branch):
//     CloseConstrainedSpan sets insideConstrainedOut := false, implication vacuously true. ✓
//
//   (dead-end escape branch):
//     CloseSpanWithinBudget postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`. ✓
//
//   (normal constrained step, non-EOS):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS. AppendConstrainedToken
//     postcondition asserts parser.IsValidPrefix on the updated currentOut. ✓
//
//   (EOS escape branch):
//     CloseSpanWithinBudget postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`. ✓
//
//   (final cleanup):
//     Same CloseSpanWithinBudget postcondition. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (budget-guard, s = steps_before):
//     CloseSpanWithinBudget(remaining) postcondition: |cg| <= |generated| + remaining.
//     remaining = maxSteps - s, so |cg| <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (!insideConstrainedOut): steps += 1; at most one token appended. ✓
//
//   (IsCompletePrefix): steps += 1; CloseConstrainedSpan appends at most one ">>" token. ✓
//
//   (dead-end escape, s = steps_before):
//     escapeBudget = min(remaining, 50) <= remaining.
//     |cg| <= |generated| + escapeBudget <= |generatedPrefix| + s + escapeBudget = |generatedPrefix| + steps'.
//     steps' = s + escapeBudget <= s + remaining = maxSteps, so steps' <= maxSteps. ✓
//
//   (normal constrained step, non-EOS): steps += 1; AppendConstrainedToken appends 1 token. ✓
//
//   (EOS escape, s_after = s + 1):
//     closeBudget2 = min(remaining2, 30) <= remaining2 = maxSteps - s_after.
//     |cg| <= |generated| + closeBudget2 <= |generatedPrefix| + s + closeBudget2 (no token appended before close).
//     steps_new = s_after + closeBudget2 = s + 1 + closeBudget2 <= s + 1 + remaining2 = maxSteps. ✓
//
//   (final cleanup): Same as budget-guard branch argument. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use only: numbers, problem variables, +, -, *, /, //, %, (), int(). " +
  "Use int() for whole-number results. " +
  "Use // for integer (floor) division. " +
  "Use exact variable names from the problem. Do not substitute numeric values for variables. " +
  "You MUST use << >> delimiters. Each << >> must contain exactly one arithmetic expression.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget guard: force close with all remaining steps
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Check for dead-end (e.g. only `!` or `>` remain as valid next tokens)
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    if narrow {
      // Dead-end escape: CloseSpanWithinBudget rolls back to last complete point
      // and emits `>>`. Use limited budget so the loop can continue afterwards.
      var escapeBudget: nat := if remaining <= 50 then remaining else 50;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, escapeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + escapeBudget;
      // Do NOT break: continue so more spans can be generated
    } else {
      // Normal constrained step with repetition penalty to discourage `!` loops
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // EOS inside open span: try to rescue the span before breaking
        var remaining2: nat := maxSteps - steps;
        if remaining2 > 0 {
          var closeBudget2: nat := if remaining2 <= 30 then remaining2 else 30;
          var cg, ci, cc := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget2
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + closeBudget2;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining3: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining3
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

